                try { return command(work, "com.mhtextractor.backend.BackendCli", "--serve", "--locale", "en"); }
                catch (Exception e) { throw new java.io.IOException(e); }
            }, Duration.ofSeconds(10));
            view.state(BackendSession.State.CONNECTED);
